use xiom.io;

type Wallet = {
  coins: Int;
  invariant: coins >= 0;
}

fn safe_move(from: &mut Wallet, to: &mut Wallet, amount: Int)
  requires: amount > 0;
  requires: amount <= from.coins;
  ensures: from.coins == from@pre.coins - amount;
  ensures: to.coins == to@pre.coins + amount;
{
  from.coins = from.coins - amount;
  to.coins = to.coins + amount;
}

fn main() -> Int {
  var a: Wallet = Wallet{ coins: 100 };
  var b: Wallet = Wallet{ coins: 50 };
  safe_move(&mut a, &mut b, 30);
  return b.coins;
}
